package cn.lambdalib.util.datapart;
public final class EntityData {private static final java.util.Map<Object,EntityData> cache=new java.util.IdentityHashMap<>();private final Object entity;private final java.util.Map<Class<?>,Object> parts=new java.util.HashMap<>();private EntityData(Object entity){this.entity=entity;}public static EntityData get(Object entity){return cache.computeIfAbsent(entity,EntityData::new);}public static void forget(Object entity){cache.remove(entity);}@SuppressWarnings("unchecked")public <T>T getPart(Class<T> clazz){return(T)parts.computeIfAbsent(clazz,type->{try{Object part=type.getConstructor().newInstance();((DataPart<Object>)part).oracleEntity=entity;return part;}catch(Exception e){throw new IllegalStateException(e);}});} }
